{
  "correction_rules": [
    "When sentiment is positive (≥ 0.25), reduce forecasted price by 5-10% to account for overconfidence bias.",
    "When sentiment is negative (≤ -0.25), increase forecasted price by 5-10% to counteract pessimism-induced undershooting.",
    "After a sharp price spike (≥ 10% from prior peak), apply a 10-15 day lag correction: reduce forecast by 5-8% for the next 3-5 days to avoid overshoot.",
    "If true outcome consistently deviates below forecast (persistent underperformance), apply mean reversion: adjust forecast toward recent 5-day average.",
    "For horizon > 15 days, reduce forecast sensitivity to recent sentiment shifts — apply a 3-day smoothing filter to sentiment before weighting.",
    "If true outcome shows strong downward trend (e.g., 3 consecutive days < 65), apply downward bias correction: reduce forecast by 3-5% per day until trend reverses."
  ]
}
